import React from 'react';
import styled from 'styled-components';
import FadeIn from './FadeIn';

const AboutContainer = styled.section`
  padding: 7rem 10vw;

  @media (max-width: 768px) {
    padding: 5rem 6vw;
  }
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 6rem;
  align-items: start;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
`;

const AsideLabel = styled.p`
  font-size: 0.68rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 2rem;
`;

const QuickFacts = styled.div`
  display: flex;
  flex-direction: column;
  gap: 0;
`;

const QFItem = styled.div`
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 1.1rem 0;
  border-bottom: 1px solid var(--border);

  &:first-child {
    border-top: 1px solid var(--border);
  }
`;

const QFKey = styled.span`
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
`;

const QFVal = styled.span`
  font-size: 0.9rem;
  color: var(--text);
`;

const Body = styled.div`
  p {
    color: var(--muted);
    margin-bottom: 1.3rem;
    font-size: 0.97rem;
    line-height: 1.95;

    strong {
      color: var(--text);
      font-weight: 500;
    }

    em {
      color: var(--accent);
      font-style: italic;
    }
  }
`;

const Tags = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 2rem;
`;

const Tag = styled.span`
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  border: 1px solid var(--border);
  padding: 0.3rem 0.85rem;
  border-radius: 100px;
  transition: all 0.2s;

  &:hover {
    border-color: var(--accent);
    color: var(--accent);
  }
`;

const quickFacts = [
  ['Based In', 'Fort Wayne, Indiana, USA'],
  ['Degree', 'MS Computer Science · Purdue'],
  ['Stack', 'React · Node · MongoDB'],
  ['Focus', 'Full Stack + Data Analytics'],
  ['Email', 'anjalipolasani4@gmail.com'],
  ['Status', 'Open to Opportunities'],
];

const tags = ['React.js', 'TypeScript', 'Node.js', 'MongoDB', 'Python', 'Power BI', 'Figma', 'UX Research', 'SEO', 'Agile'];

const AboutSection = () => {
  return (
    <AboutContainer id="about">
      <Grid>
        <FadeIn>
          <div>
            <AsideLabel>Quick Facts</AsideLabel>
            <QuickFacts>
              {quickFacts.map(([key, val]) => (
                <QFItem key={key}>
                  <QFKey>{key}</QFKey>
                  <QFVal>{val}</QFVal>
                </QFItem>
              ))}
            </QuickFacts>
          </div>
        </FadeIn>

        <FadeIn delay={150}>
          <div>
            <p className="section-label">About Me</p>
            <h2 className="section-title">
              Building at the intersection of code &amp; craft
            </h2>
            <Body>
              <p>
                I'm <strong>Anjali Polasani</strong>, a Computer Science graduate student at Purdue
                University with a deep love for building things that live on the web. I come from a
                full-stack world — comfortable writing a REST API in the morning and refining a UI
                component in the afternoon.
              </p>
              <p>
                What sets me apart? I think in <strong>systems</strong>. Whether it's mapping a
                user's checkout journey or designing a database schema, I'm always thinking about
                how pieces fit together. My background in{' '}
                <strong>data analytics, UX research, and digital marketing</strong> means I don't
                just build features — I understand why they matter.
              </p>
              <p>
                I've shipped production code during internships at <strong>AICTE and Code Alpha</strong>,
                run usability studies on real products like DoorDash, and built full-stack apps
                end-to-end from schema design to deployment. I bring data intuition — Power BI
                dashboards, cohort analysis, A/B testing — alongside every feature I ship.
              </p>
              <p>
                When I'm not coding, I'm exploring data visualizations, experimenting with UI
                animations, or reading about product design. I believe the best software is
                invisible — it just <em>works</em>.
              </p>
            </Body>
            <Tags>
              {tags.map((t) => <Tag key={t}>{t}</Tag>)}
            </Tags>
          </div>
        </FadeIn>
      </Grid>
    </AboutContainer>
  );
};

export default AboutSection;
